package vn.svframe.lively.event;
import vn.svframe.lively.actor.ActorId;import vn.svframe.lively.world.SemanticStructureRegistry;import vn.svframe.lively.world.WorldMutationPolicy;import java.time.*;import java.util.*;import java.util.concurrent.*;public final class WorldEventEngine{public enum Category{CRIME,SOCIAL,ECONOMIC,FACTION_CONFLICT,FESTIVAL,DISASTER,MYSTERY,MIGRATION,POLITICAL,DISCOVERY}public enum Phase{PROPOSED,ACTIVE,PAUSED,RESOLVING,FINISHED,CANCELLED}public interface Listener{default void onStarted(WorldEvent e){}default void onFinished(WorldEvent e){}default void onCancelled(WorldEvent e){}}public record EventProposal(Category category,String seed,String structureId,Set<ActorId>participants,double intensity,Duration duration,Map<String,String>facts){public EventProposal{Objects.requireNonNull(category);Objects.requireNonNull(seed);Objects.requireNonNull(duration);participants=Set.copyOf(participants);facts=Map.copyOf(facts);intensity=Math.max(0D,Math.min(1D,intensity));}}public record WorldEvent(UUID id,Category category,String seed,String structureId,Set<ActorId>participants,double intensity,Instant startedAt,Instant expiresAt,Phase phase,Map<String,String>facts){public WorldEvent{Objects.requireNonNull(id);Objects.requireNonNull(category);Objects.requireNonNull(seed);Objects.requireNonNull(startedAt);Objects.requireNonNull(expiresAt);Objects.requireNonNull(phase);participants=Set.copyOf(participants);facts=Map.copyOf(facts);}public boolean expired(Instant now){return!expiresAt.isAfter(now);}public WorldEvent withPhase(Phase next){return new WorldEvent(id,category,seed,structureId,participants,intensity,startedAt,expiresAt,next,facts);}}private final ConcurrentHashMap<UUID,WorldEvent>active=new ConcurrentHashMap<>();private final List<WorldEvent>history=Collections.synchronizedList(new ArrayList<>());private final CopyOnWriteArrayList<Listener>listeners=new CopyOnWriteArrayList<>();private final SemanticStructureRegistry structures;private final WorldMutationPolicy policy;private final int maxActive;public WorldEventEngine(SemanticStructureRegistry s,WorldMutationPolicy p,int max){structures=s;policy=p;maxActive=Math.max(1,Math.min(10000,max));}public void addListener(Listener l){listeners.addIfAbsent(l);}public Validation validate(EventProposal p){if(active.size()>=maxActive)return Validation.deny("active_event_limit");if(p.seed().isBlank()||p.seed().length()>128)return Validation.deny("invalid_seed");if(p.duration().isNegative()||p.duration().isZero()||p.duration().compareTo(Duration.ofDays(30))>0)return Validation.deny("invalid_duration");if(p.participants().size()>256||p.facts().size()>128)return Validation.deny("too_large");if(p.structureId()!=null&&structures.get(p.structureId()).isEmpty())return Validation.deny("unknown_structure");return Validation.allow();}public Optional<WorldEvent>start(EventProposal p){if(!validate(p).allowed())return Optional.empty();if(!policy.evaluate(new WorldMutationPolicy.Proposal(null,WorldMutationPolicy.Source.SYSTEM,WorldMutationPolicy.MutationClass.SEMANTIC,WorldMutationPolicy.ActionKind.EVENT_STATE,p.structureId(),null,Map.of("seed",p.seed()))).allowed())return Optional.empty();Instant now=Instant.now();WorldEvent e=new WorldEvent(UUID.randomUUID(),p.category(),p.seed(),p.structureId(),p.participants(),p.intensity(),now,now.plus(p.duration()),Phase.ACTIVE,p.facts());active.put(e.id(),e);listeners.forEach(l->safe(()->l.onStarted(e)));return Optional.of(e);}public Optional<WorldEvent>pause(UUID id){return Optional.ofNullable(active.computeIfPresent(id,(k,e)->e.phase()==Phase.ACTIVE?e.withPhase(Phase.PAUSED):e)).filter(e->e.phase()==Phase.PAUSED);}public Optional<WorldEvent>resume(UUID id){return Optional.ofNullable(active.computeIfPresent(id,(k,e)->e.phase()==Phase.PAUSED?e.withPhase(Phase.ACTIVE):e)).filter(e->e.phase()==Phase.ACTIVE);}public Optional<WorldEvent>finish(UUID id){WorldEvent e=active.remove(id);if(e==null)return Optional.empty();WorldEvent done=e.withPhase(Phase.FINISHED);history.add(done);listeners.forEach(l->safe(()->l.onFinished(done)));return Optional.of(done);}public Optional<WorldEvent>cancel(UUID id){WorldEvent e=active.remove(id);if(e==null)return Optional.empty();WorldEvent c=e.withPhase(Phase.CANCELLED);history.add(c);listeners.forEach(l->safe(()->l.onCancelled(c)));return Optional.of(c);}public int advance(Instant now){int n=0;for(WorldEvent e:List.copyOf(active.values())){if(e.phase()==Phase.PAUSED||!e.expired(now))continue;WorldEvent done=e.withPhase(Phase.FINISHED);if(active.remove(e.id(),e)){history.add(done);n++;listeners.forEach(l->safe(()->l.onFinished(done)));}}return n;}public List<WorldEvent>activeEvents(){return List.copyOf(active.values());}public List<WorldEvent>history(){synchronized(history){return List.copyOf(history);}}public Snapshot snapshot(){synchronized(history){return new Snapshot(Map.copyOf(active),List.copyOf(history));}}public void restore(Snapshot s){active.clear();for(var e:s.active().entrySet())if(Set.of(Phase.ACTIVE,Phase.PAUSED,Phase.RESOLVING).contains(e.getValue().phase()))active.put(e.getKey(),e.getValue());synchronized(history){history.clear();history.addAll(s.history().stream().limit(100000).toList());}}public record Snapshot(Map<UUID,WorldEvent>active,List<WorldEvent>history){public Snapshot{active=Map.copyOf(active);history=List.copyOf(history);}}private static void safe(Runnable r){try{r.run();}catch(RuntimeException ignored){}}public record Validation(boolean allowed,String reason){public static Validation allow(){return new Validation(true,"accepted");}public static Validation deny(String r){return new Validation(false,r);}}}
